import java.io.*;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = System.in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static long readLong() throws IOException {
        int c = readByte();
        while (c != -1 && (c < '0' || c > '9')) c = readByte();
        long x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) readLong(), m = (int) readLong();
        int[] a = new int[n]; // values fit in int (< 10^9)
        long total = 0;
        for (int i = 0; i < n; i++) {
            a[i] = (int) readLong();
            total += a[i];
        }
        long cur = 0;
        for (int i = 0; i < m; i++) cur += a[i];
        long best = cur;
        // Slide the length-m window: gain a[i], lose a[i - m].
        for (int i = m; i < n; i++) {
            cur += a[i] - a[i - m];
            if (cur > best) best = cur;
        }
        System.out.println(total - best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() int64 {
		c, err := reader.ReadByte()
		for err == nil && (c < '0' || c > '9') {
			c, err = reader.ReadByte()
		}
		var x int64
		for err == nil && c >= '0' && c <= '9' {
			x = x*10 + int64(c-'0')
			c, err = reader.ReadByte()
		}
		return x
	}
	n, m := int(readInt()), int(readInt())
	a := make([]int64, n)
	var total int64
	for i := range a {
		a[i] = readInt()
		total += a[i]
	}
	var cur int64
	for i := 0; i < m; i++ {
		cur += a[i]
	}
	best := cur
	// Slide the length-m window: gain a[i], lose a[i-m].
	for i := m; i < n; i++ {
		cur += a[i] - a[i-m]
		best = max(best, cur)
	}
	fmt.Println(total - best)
}
